  'IBAN utilisé': ['Verwendete IBAN', 'IBAN usato', 'IBAN used'],
  'IBAN utilisés': ['Verwendete IBAN', 'IBAN usati', 'IBANs used'],
  'Approuvé par {name}': ['Freigegeben von {name}', 'Approvato da {name}', 'Approved by {name}'],
  'Le montant ou l’IBAN a changé depuis l’approbation : à approuver à nouveau.': ['Betrag oder IBAN haben sich seit der Freigabe geändert: erneut freigeben.', 'L’importo o l’IBAN sono cambiati dall’approvazione: da approvare di nuovo.', 'The amount or IBAN changed since the approval: approve it again.'],
  'En attente d’approbation par une autre personne': ['Wartet auf die Freigabe durch eine andere Person', 'In attesa di approvazione da parte di un’altra persona', 'Waiting for approval by another person'],
  'Préparé par {name} · à approuver': ['Vorbereitet von {name} · freizugeben', 'Preparato da {name} · da approvare', 'Prepared by {name} · to approve'],
  'À partir de {amount}, une deuxième personne approuve le paiement.': ['Ab {amount} gibt eine zweite Person die Zahlung frei.', 'A partire da {amount}, una seconda persona approva il pagamento.', 'From {amount}, a second person approves the payment.'],
  'Ligne « {line} » : compte {account} jamais utilisé pour ce fournisseur.': ['Zeile «{line}»: Konto {account} wurde für diesen Lieferanten noch nie verwendet.', 'Riga «{line}»: conto {account} mai usato per questo fornitore.', 'Line “{line}”: account {account} never used for this supplier.'],
  'sans compte': ['ohne Konto', 'senza conto', 'no account'],
  'Ligne « {line} » : TVA {rate}, jamais utilisée pour ce fournisseur.': ['Zeile «{line}»: MWST {rate}, für diesen Lieferanten noch nie verwendet.', 'Riga «{line}»: IVA {rate}, mai usata per questo fornitore.', 'Line “{line}”: VAT {rate}, never used for this supplier.'],
  'Montant plus de {factor} fois supérieur à l’habitude ({usual}).': ['Betrag mehr als {factor}-mal höher als üblich ({usual}).', 'Importo oltre {factor} volte superiore al solito ({usual}).', 'Amount more than {factor} times the usual ({usual}).'],
  'D’habitude, {supplier} va en {account} avec TVA {rate}.': ['Üblicherweise wird {supplier} auf {account} mit MWST {rate} gebucht.', 'Di solito {supplier} va su {account} con IVA {rate}.', '{supplier} usually goes to {account} with VAT {rate}.'],
  'D’habitude, {supplier} va en {account}.': ['Üblicherweise wird {supplier} auf {account} gebucht.', 'Di solito {supplier} va su {account}.', '{supplier} usually goes to {account}.'],
  'Justificatif à transmettre : {amount} du {date}': ['Beleg einzureichen: {amount} vom {date}', 'Giustificativo da trasmettere: {amount} del {date}', 'Receipt to send: {amount} of {date}'],
  'Bonjour {name},': ['Hallo {name}', 'Ciao {name},', 'Hello {name},'],
  'Il nous manque le justificatif de cette dépense :': ['Uns fehlt der Beleg für diese Ausgabe:', 'Ci manca il giustificativo di questa spesa:', 'We are missing the receipt for this expense:'],
